<script setup lang="ts">
interface Tool { name: string; tagline: string; description: string; icon: string; tone: string; category: string; featured?: boolean }
interface UploadedImage { id: number; name: string; src: string }
interface ImageResult { id: number; ratio: string; size: string; title: string; detail: string; tone: string; status?: 'completed' | 'generating'; model?: string; format?: string; createdAt?: string; generationStartedAt?: number }
const tools: Tool[] = [
  { name: 'ChatGPT', tagline: '智能对话助手', description: '写作、头脑风暴、学习与日常问答的全能 AI 助手。', icon: '✦', tone: 'blue', category: 'AI 写作', featured: true },
  { name: 'Claude', tagline: '长文本 AI 助手', description: '擅长深度分析、长文写作和复杂任务处理。', icon: 'C', tone: 'purple', category: 'AI 写作', featured: true },
  { name: 'Midjourney', tagline: 'AI 艺术创作', description: '将文字描述转化为高质量、富有想象力的视觉作品。', icon: 'M', tone: 'peach', category: '图像设计', featured: true },
  { name: 'Runway', tagline: 'AI 视频创作', description: '使用生成式 AI 制作、编辑和增强视频内容。', icon: '▶', tone: 'mint', category: '视频创作', featured: true },
  { name: 'Notion AI', tagline: '智能工作空间', description: '在笔记、文档和项目空间中快速总结、改写与生成内容。', icon: 'N', tone: 'blue', category: '效率办公' },
  { name: 'Cursor', tagline: 'AI 编程编辑器', description: '理解代码库并协助编写、重构和调试代码。', icon: '</>', tone: 'purple', category: '开发编程' },
  { name: 'Suno', tagline: 'AI 音乐生成', description: '从一句灵感描述开始，创作完整歌曲与音乐作品。', icon: '♫', tone: 'peach', category: '音频音乐' },
  { name: 'Perplexity', tagline: 'AI 搜索引擎', description: '结合实时检索与智能总结，快速找到可靠答案。', icon: 'P', tone: 'mint', category: '效率办公' }
]
const query = ref(''); const activeView = ref<'discover' | 'blank'>('discover'); const activeToolTab = ref<'image' | 'watermark'>('image'); const activeCategory = ref('全部工具');
const imageForm = reactive({ model: 'gpt-image-2.5', prompt: '', size: 'auto', quality: 'auto', format: 'PNG', transparent: '否', quantity: 1 }); const uploadedImages = ref<UploadedImage[]>([]); const uploadInput = ref<HTMLInputElement | null>(null); let uploadedImageSequence = 0; const previewImageIndex = ref<number | null>(null); const previewImage = computed(() => previewImageIndex.value === null ? null : uploadedImages.value[previewImageIndex.value] ?? null); const showImageSizeModal = ref(false); const imageSizeMode = ref<'auto' | 'ratio' | 'custom'>('auto'); const imageSizeResolution = ref<'standard1k' | 'high2k' | 'ultra4k'>('standard1k'); const imageSizeRatio = ref('1:1'); const imageCustomRatio = ref('16:9'); const imageFilters = reactive({ category: '全部', search: '', model: '所有模型', mode: '全部模式' }); const selectedImage = ref<ImageResult | null>(null); const generationTick = ref(0); let generationTimer: ReturnType<typeof setInterval> | undefined;
const imageSamples = [
  { ratio: '1:1', size: '1024×1024', title: '雨后街头的城市光影', detail: '换个雨后街头场景，换个表情，再来一张', tone: 'sunset' },
  { ratio: '3:2', size: '1536×1024', title: '蓝发少女插画', detail: '把这张图中的任务生成一张红底证件照，大头贴那种', tone: 'violet' },
  { ratio: '3:2', size: '1536×1024', title: '角色概念设计', detail: '把这张图中的任务生成一张红底证件照，大头贴那种', tone: 'sky' },
  { ratio: '3:2', size: '1536×1024', title: '轻盈明亮的角色头像', detail: '把这张图中的任务生成一张红底证件照，大头贴那种', tone: 'coral' },
  { ratio: '1:1', size: '1024×1024', title: '雨中人物街拍', detail: '换个雨后街头场景，换个表情，换个姿势，再来一张', tone: 'forest' },
  { ratio: '1:1', size: '1024×1024', title: '自然光人像', detail: '换个雨后街头场景，换个表情，换个姿势，再来一张', tone: 'amber' },
  { ratio: '1:1', size: '1024×1024', title: '电影感构图', detail: '帮我生成图片，9:16 竖版构图，2K 超高清、Ultra HD', tone: 'mist' },
  { ratio: '1:1', size: '1024×1024', title: '服装材质参考', detail: '严格参考输入图片中的服装款式、颜色、图案与材质', tone: 'blue' }
]; let imageResultSequence = imageSamples.length; const imageResults = ref<ImageResult[]>(imageSamples.map((sample, index) => ({ ...sample, id: index + 1, status: 'completed' as const, model: 'gpt-image-2', format: 'PNG', createdAt: '2026/10/02 21:38:54' }))); const favorites = ref<string[]>([]); const workspaceToolNames = ref<string[]>(['ChatGPT', 'Claude', 'Notion AI', 'Cursor']); const selectedTool = ref<Tool | null>(null); const toast = ref(''); const showAuth = ref(false); const authMode = ref<'login' | 'register'>('login'); const currentUser = ref<{ name: string; email: string } | null>(null); const authForm = reactive({ name: '', email: '', password: '', confirmPassword: '', remember: true }); let toastTimer: ReturnType<typeof setTimeout> | undefined
const imageSizeLabel = computed(() => {
  if (imageSizeMode.value === 'auto') return '自动'
  const ratio = imageSizeMode.value === 'custom' ? imageCustomRatio.value.trim() : imageSizeRatio.value
  const baseDimensions: Record<string, [number, number]> = {
    '1:1': [1024, 1024], '4:5': [1024, 1280], '3:4': [1024, 1365], '2:3': [1024, 1536], '9:16': [1024, 1792],
    '3:2': [1536, 1024], '4:3': [1365, 1024], '16:9': [1792, 1024], '21:9': [1792, 768], '5:4': [1280, 1024],
    '5:7': [1024, 1434], '7:5': [1434, 1024], '2:1': [1536, 768], '1:2': [768, 1536], '9:21': [768, 1792]
  }
  let dimensions = baseDimensions[ratio]
  if (!dimensions) {
    const match = ratio.match(/^(\d+(?:\.\d+)?)\s*:\s*(\d+(?:\.\d+)?)$/)
    if (match) {
      const widthRatio = Number(match[1]); const heightRatio = Number(match[2])
      if (widthRatio > 0 && heightRatio > 0) {
        const scale = Math.max(widthRatio, heightRatio) <= 1 ? 1024 / Math.max(widthRatio, heightRatio) : 1024 / Math.max(widthRatio, heightRatio)
        dimensions = [Math.round(widthRatio * scale), Math.round(heightRatio * scale)]
      }
    }
  }
  if (!dimensions) return ratio || '自动'
  const resolutionScale = { standard1k: 1, high2k: 2, ultra4k: 4 }[imageSizeResolution.value]
  return `${Math.round(dimensions[0] * resolutionScale)}×${Math.round(dimensions[1] * resolutionScale)}`
}); 
const popularTools = computed(() => tools.filter(tool => tool.featured)); const isFavorite = (tool: Tool) => favorites.value.includes(tool.name); const favoriteTools = computed(() => tools.filter(tool => isFavorite(tool))); const workspaceTools = computed(() => workspaceToolNames.value.map(name => tools.find(tool => tool.name === name)).filter((tool): tool is Tool => Boolean(tool))); const sidebarCategories = ['中转站', 'skill', 'harness', 'Agent', 'MCP', '插件']; const categorySections = computed(() => sidebarCategories.filter(category => category !== '常用工具').map(category => ({ category, tools: tools.filter(tool => tool.category === category).slice(0, 8) })))
function notify(message: string) { toast.value = message; if (toastTimer) clearTimeout(toastTimer); toastTimer = setTimeout(() => { toast.value = '' }, 2200) }
function toggleFavorite(tool: Tool) { favorites.value = isFavorite(tool) ? favorites.value.filter(name => name !== tool.name) : [...favorites.value, tool.name]; localStorage.setItem('ai-navigation-favorites', JSON.stringify(favorites.value)); notify(isFavorite(tool) ? '已加入我的收藏' : '已取消收藏') }
function addWorkspaceTool(tool: Tool) {
  if (workspaceToolNames.value.includes(tool.name)) return
  if (workspaceToolNames.value.length >= 6) {
    notify('工作台最多固定 6 个工具')
    return
  }
  workspaceToolNames.value = [...workspaceToolNames.value, tool.name]
  localStorage.setItem('ai-navigation-workspace-tools', JSON.stringify(workspaceToolNames.value))
  notify('已将 ' + tool.name + ' 放到工作台')
}
function generateImages() { if (!imageForm.prompt.trim()) { notify('请先描述你想创建的图片'); return }; const quantity = Math.min(10, Math.max(1, Number(imageForm.quantity) || 1)); const prompt = imageForm.prompt.trim(); const ratio = imageSizeMode.value === 'custom' ? imageCustomRatio.value.trim() || '1:1' : imageSizeMode.value === 'ratio' ? imageSizeRatio.value : '1:1'; const startedAt = Date.now(); const title = prompt.length > 28 ? `${prompt.slice(0, 28)}…` : prompt; const generatedResults: ImageResult[] = Array.from({ length: quantity }, (_, index) => ({ id: ++imageResultSequence, ratio, size: imageForm.size || 'auto', title: quantity > 1 ? `${title}（${index + 1}/${quantity}）` : title, detail: prompt, tone: imageSamples[index % imageSamples.length].tone, status: 'generating', model: imageForm.model, format: imageForm.format, generationStartedAt: startedAt })); imageResults.value = [...generatedResults, ...imageResults.value]; notify(`已提交 ${quantity} 张图片生成任务`) }
function openImageResult(sample: ImageResult) { if (sample.status === 'generating') return; selectedImage.value = sample }
function formatElapsed(sample: ImageResult) { generationTick.value; if (!sample.generationStartedAt) return '00:00'; const elapsed = Math.max(0, Math.floor((Date.now() - sample.generationStartedAt) / 1000)); const minutes = String(Math.floor(elapsed / 60)).padStart(2, '0'); const seconds = String(elapsed % 60).padStart(2, '0'); return `${minutes}:${seconds}` }
function formatGenerationTime(sample: ImageResult) { if (!sample.generationStartedAt) return ''; return new Date(sample.generationStartedAt).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', hour12: false }) }
function openImageUpload() { uploadInput.value?.click() }
function handleImageUpload(event: Event) {
  const input = event.target as HTMLInputElement
  const files = Array.from(input.files ?? [])
  if (!files.length) return
  const remaining = Math.max(0, 9 - uploadedImages.value.length)
  const nextImages = files.slice(0, remaining).map(file => ({ id: ++uploadedImageSequence, name: file.name, src: URL.createObjectURL(file) }))
  uploadedImages.value = [...uploadedImages.value, ...nextImages]
  input.value = ''
  notify(nextImages.length === 1 ? '已添加参考图片' : `已添加 ${nextImages.length} 张参考图片`)
}
function removeUploadedImage(index: number) {
  const image = uploadedImages.value[index]
  if (!image) return
  URL.revokeObjectURL(image.src)
  uploadedImages.value.splice(index, 1)
  if (previewImageIndex.value !== null) {
    if (!uploadedImages.value.length) previewImageIndex.value = null
    else if (index < previewImageIndex.value) previewImageIndex.value -= 1
    else if (index === previewImageIndex.value) previewImageIndex.value = Math.min(index, uploadedImages.value.length - 1)
  }
  notify('已移除参考图片')
}
function clearUploadedImages() {
  uploadedImages.value.forEach(image => URL.revokeObjectURL(image.src))
  uploadedImages.value = []
  previewImageIndex.value = null
  notify('已移除参考图片')
}
function openUploadedImagePreview(index: number) { previewImageIndex.value = index }
function closeUploadedImagePreview() { previewImageIndex.value = null }
function showPreviousUploadedImage() {
  if (!uploadedImages.value.length || previewImageIndex.value === null) return
  previewImageIndex.value = (previewImageIndex.value - 1 + uploadedImages.value.length) % uploadedImages.value.length
}
function showNextUploadedImage() {
  if (!uploadedImages.value.length || previewImageIndex.value === null) return
  previewImageIndex.value = (previewImageIndex.value + 1) % uploadedImages.value.length
}
function openImageSizeModal() { showImageSizeModal.value = true }
function cancelImageSize() { showImageSizeModal.value = false }
function confirmImageSize() { imageForm.size = imageSizeLabel.value; showImageSizeModal.value = false }
function showDiscover() { activeView.value = 'discover' }
function openCommonToolsPage() { activeView.value = 'blank'; activeCategory.value = '常用工具' }
function selectCategory(category: string) { activeView.value = 'discover'; activeCategory.value = category; const target = category === '常用工具' ? 'workspace-tools' : 'category-sections'; document.getElementById(target)?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
function showFavorites() { activeView.value = 'discover'; notify(favorites.value.length ? `已筛选 ${favorites.value.length} 个收藏工具` : '还没有收藏工具'); document.getElementById('category-sections')?.scrollIntoView({ behavior: 'smooth', block: 'start' }) }
function openAuth(mode: 'login' | 'register' = 'login') { authMode.value = mode; showAuth.value = true }
function closeAuth() { showAuth.value = false; authForm.password = ''; authForm.confirmPassword = '' }
function submitAuth() {
  const email = authForm.email.trim().toLowerCase(); const password = authForm.password
  if (!email || !password) return notify('请填写邮箱和密码')
  if (!/^\S+@\S+\.\S+$/.test(email)) return notify('请输入有效的邮箱地址')
  if (password.length < 6) return notify('密码至少需要 6 位')
  const users = JSON.parse(localStorage.getItem('ai-navigation-users') || '{}') as Record<string, { name: string; email: string; password: string }>
  if (authMode.value === 'register') { if (!authForm.name.trim()) return notify('请输入昵称'); if (password !== authForm.confirmPassword) return notify('两次输入的密码不一致'); if (users[email]) return notify('该邮箱已注册，请直接登录'); users[email] = { name: authForm.name.trim(), email, password }; localStorage.setItem('ai-navigation-users', JSON.stringify(users)); currentUser.value = { name: users[email].name, email }; localStorage.setItem('ai-navigation-session', JSON.stringify(currentUser.value)); closeAuth(); return notify('注册成功，欢迎加入灵感 AI 导航') }
  const user = users[email]; if (!user || user.password !== password) return notify('邮箱或密码错误'); currentUser.value = { name: user.name, email: user.email }; localStorage.setItem('ai-navigation-session', JSON.stringify(currentUser.value)); closeAuth(); notify(`欢迎回来，${user.name}`)
}
function logout() { currentUser.value = null; localStorage.removeItem('ai-navigation-session'); notify('已退出登录') }
function handleKeydown(event: KeyboardEvent) { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); document.getElementById('search')?.focus() } if (previewImageIndex.value !== null) { if (event.key === 'Escape') { event.preventDefault(); closeUploadedImagePreview(); return } if (event.key === 'ArrowLeft') { event.preventDefault(); showPreviousUploadedImage(); return } if (event.key === 'ArrowRight') { event.preventDefault(); showNextUploadedImage(); return } } if (event.key === 'Escape') { selectedTool.value = null; selectedImage.value = null; showImageSizeModal.value = false; closeAuth() } }
useSeoMeta({ title: '灵感 AI 导航｜精选 AI 工具与效率应用', description: '灵感 AI 导航汇集 AI 写作、图像设计、视频创作、效率办公、开发编程与音频音乐工具，帮助你快速发现适合自己的 AI 应用。', ogTitle: '灵感 AI 导航｜精选 AI 工具与效率应用', ogDescription: '发现值得使用的 AI 工具，提升创作与工作效率。', ogType: 'website', twitterCard: 'summary_large_image' })
useHead({ link: [{ rel: 'canonical', href: '/' }], script: [{ type: 'application/ld+json', children: computed(() => JSON.stringify({ '@context': 'https://schema.org', '@type': 'WebSite', name: '灵感 AI 导航', url: '/', description: '精选 AI 工具导航网站', potentialAction: { '@type': 'SearchAction', target: '/?q={search_term_string}', 'query-input': 'required name=search_term_string' } })) }] })
onMounted(() => { const session = localStorage.getItem('ai-navigation-session'); if (session) currentUser.value = JSON.parse(session); const saved = localStorage.getItem('ai-navigation-favorites'); if (saved) favorites.value = JSON.parse(saved); const savedWorkspace = localStorage.getItem('ai-navigation-workspace-tools'); if (savedWorkspace) workspaceToolNames.value = JSON.parse(savedWorkspace); generationTimer = setInterval(() => { generationTick.value += 1 }, 1000); window.addEventListener('keydown', handleKeydown) })
onBeforeUnmount(() => { window.removeEventListener('keydown', handleKeydown); if (toastTimer) clearTimeout(toastTimer); if (generationTimer) clearInterval(generationTimer) })
</script>
<template>
  <div class="app-shell">
    <aside class="sidebar"><a class="brand" href="#top" aria-label="灵感 AI 导航首页"><span class="brand-mark">✦</span><span>灵感 AI 导航</span></a><div class="sidebar-scroll"><div class="nav-label">工作台</div><nav class="main-nav"><a :class="{ active: activeView === 'discover' }" href="#top" @click="showDiscover"><span class="nav-icon">⌂</span>发现</a><a href="#tools" @click.prevent="showFavorites"><span class="nav-icon">♡</span>我的收藏<em v-if="favoriteTools.length">{{ favoriteTools.length }}</em></a><a href="#tools" @click.prevent="notify('最近使用功能即将开放')"><span class="nav-icon">◷</span>最近使用</a><a :class="{ active: activeView === 'blank' }" href="#common-tools" @click.prevent="openCommonToolsPage"><span class="nav-icon">⌘</span>常用工具</a></nav><div class="nav-label">工具分类</div><nav class="main-nav"><a v-for="category in sidebarCategories" :key="category" href="#category-sections" @click.prevent="selectCategory(category)"><span class="nav-icon">{{ category === '常用工具' ? '⌘' : category === '中转站' ? '↔' : category === 'skill' ? '◇' : category === 'harness' ? '◌' : category === 'Agent' ? '⊙' : category === 'MCP' ? '⬢' : '⊞' }}</span>{{ category }}</a></nav></div><div class="sidebar-bottom"><div class="upgrade"><strong>注册后解锁更多可能</strong><p>注册后即可收藏喜欢的工具，打造专属 AI 工作台。</p><button type="button" @click="openAuth('register')">立即注册</button></div><button type="button" class="profile profile-button" @click="currentUser ? logout() : openAuth()"><span class="avatar">{{ currentUser ? currentUser.name.slice(0, 1) : '你' }}</span><div><strong>{{ currentUser?.name || '探索者' }}</strong><small>{{ currentUser ? '点击退出登录' : '登录 / 注册' }}</small></div></button></div></aside>
    <main id="top" class="main-content"><template v-if="activeView === 'blank'"><header class="topbar"><div class="breadcrumb"><span>工作台</span><b>/</b><strong>常用工具</strong></div><div class="top-actions"><button type="button" aria-label="返回发现" @click="showDiscover">↩</button></div></header><section class="blank-page-shell common-tools-page" aria-label="常用工具"><div class="common-tools-tabs" role="tablist" aria-label="常用工具类型"><button type="button" role="tab" :aria-selected="activeToolTab === 'image'" :class="{ active: activeToolTab === 'image' }" @click="activeToolTab = 'image'">AI生图</button><button type="button" role="tab" :aria-selected="activeToolTab === 'watermark'" :class="{ active: activeToolTab === 'watermark' }" @click="activeToolTab = 'watermark'">去水印</button></div><div v-if="activeToolTab === 'image'" class="common-tool-panel image-tool-panel" role="tabpanel">
  <div class="image-tool-heading"><div><span class="common-tool-icon peach">✦</span><div><h2>AI生图</h2><p>输入描述，快速生成你的专属图片。</p></div></div><button type="button" class="image-history-button" @click="notify('历史记录功能即将开放')">生成记录 <b>↗</b></button></div>
  <div class="image-tool-toolbar"><button type="button" class="image-round-button" aria-label="收藏筛选">♡</button><select v-model="imageFilters.category" aria-label="图片分类"><option>全部</option><option>人物</option><option>风景</option><option>插画</option></select><label class="image-search"><span>⌕</span><input v-model="imageFilters.search" type="search" placeholder="搜索图片" aria-label="搜索图片" /></label><button type="button" class="image-filter-button" @click="notify('筛选条件已准备')">☷</button><select v-model="imageFilters.model" aria-label="模型筛选"><option>所有模型</option><option>gpt-image-2.5</option><option>gpt-image-2</option></select><select v-model="imageFilters.mode" aria-label="模式筛选"><option>全部模式</option><option>文生图</option><option>图生图</option></select><button type="button" class="image-favorite-button" @click="notify('收藏夹功能即将开放')">♡ 新建收藏夹</button><select aria-label="收藏夹管理"><option>管理收藏夹</option><option>默认收藏夹</option></select></div>
  <div class="image-gallery"><article v-for="sample in imageResults" :key="sample.id" class="image-result-card" :class="{ 'is-generating': sample.status === 'generating' }" role="button" :aria-disabled="sample.status === 'generating'" tabindex="0" @click="openImageResult(sample)" @keydown.enter="openImageResult(sample)"><div v-if="sample.status === 'generating'" class="image-result-preview image-generating-preview"><span class="image-generating-time">{{ formatElapsed(sample) }}</span><div class="image-generating-state"><span class="image-generating-spinner" aria-hidden="true"></span><span>进行中</span></div></div><div v-else class="image-result-preview" :class="`image-tone-${sample.tone}`"><span class="image-badge">{{ sample.ratio }}</span><span class="image-size-badge">{{ sample.size }}</span><span class="image-placeholder-mark">✦</span></div><div class="image-result-copy"><template v-if="sample.status === 'generating'"><strong>{{ sample.title }}</strong><p>{{ sample.detail }}</p><small>创建于 {{ formatGenerationTime(sample) }}</small><div class="image-result-tags"><span>{{ sample.model }}</span><span>{{ sample.ratio }}</span></div><div class="image-generating-meta">{{ sample.size }} · {{ sample.format }}</div></template><template v-else><strong>{{ sample.title }}</strong><p>{{ sample.detail }}</p><small>创建于 {{ sample.createdAt }} · 耗时 00:41</small><div class="image-result-tags"><span>{{ sample.model }}</span><button type="button" @click.stop="notify('编辑提示词功能即将开放')">编辑</button></div><div class="image-result-actions"><button type="button" aria-label="收藏" @click.stop="notify('已收藏图片')">♡</button><button type="button" aria-label="重新生成" @click.stop="notify('已提交重新生成任务')">↻</button><button type="button" aria-label="复制" @click.stop="notify('已复制图片')">♧</button><button type="button" aria-label="删除" @click.stop="notify('已移入回收站')">♧</button></div></template></div></article></div>
  <section class="image-composer" :class="{ 'has-uploaded-images': uploadedImages.length > 0 }" aria-label="图片生成设置">
    <div v-if="uploadedImages.length" class="image-reference-strip" aria-label="已上传参考图片">
      <div class="image-reference-list">
        <div v-for="(image, index) in uploadedImages" :key="image.id" class="image-reference-thumb">
          <button type="button" class="image-reference-preview" :aria-label="`预览第 ${index + 1} 张图片`" @click="openUploadedImagePreview(index)">
            <img :src="image.src" :alt="image.name" />
            <span v-if="index === 0 && uploadedImages.length > 1" class="image-reference-count">{{ uploadedImages.length }}</span>
          </button>
          <button type="button" class="image-reference-remove" :aria-label="`移除第 ${index + 1} 张参考图片`" @click.stop="removeUploadedImage(index)">×</button>
        </div>      </div>
      <div class="image-reference-actions">
        <button type="button" class="image-reference-edit" @click="openImageUpload"><span aria-hidden="true">✎</span> 编辑</button>
        <button type="button" class="image-reference-delete" aria-label="删除全部参考图片" @click="clearUploadedImages">🗑</button>
      </div>
    </div>
    <textarea v-model="imageForm.prompt" rows="2" placeholder="描述你想创建的图片"></textarea>
    <div class="image-model-row"><select v-model="imageForm.model" aria-label="生成模型"><option value="gpt-image-2.5">gpt-image-2.5</option><option value="gpt-image-2">gpt-image-2</option></select></div>
    <div class="image-composer-meta"><span>预计消耗（参考）</span><span>以实际模型计费为准</span><b>·</b><span>生成</span><b>·</b><span>数量 {{ imageForm.quantity }}</span><b>·</b><span>{{ imageForm.format }}</span></div>
    <div class="image-options"><label>尺寸<button type="button" class="image-option-button" aria-label="尺寸" @click="openImageSizeModal">{{ imageSizeLabel }} <span>⌄</span></button></label><label>质量<select v-model="imageForm.quality" aria-label="质量"><option value="auto">自动</option><option value="standard">标准</option><option value="high">高清</option></select></label><label>格式<select v-model="imageForm.format" aria-label="格式"><option>PNG</option><option>JPEG</option><option>WebP</option></select></label><label>透明背景<select v-model="imageForm.transparent" aria-label="透明背景"><option>否</option><option>是</option></select></label><label>数量<input v-model.number="imageForm.quantity" min="1" max="10" type="number" aria-label="数量" /></label><button type="button" class="image-upload-button" @click="openImageUpload">▧ 上传图片</button><button type="button" class="image-generate-button" @click="generateImages">✣ 生成</button></div>
    <input ref="uploadInput" class="image-upload-input" type="file" accept="image/*" multiple aria-label="上传参考图片" @change="handleImageUpload" />
  </section><div v-if="previewImage" class="uploaded-image-preview-backdrop" @click.self="closeUploadedImagePreview"><article class="uploaded-image-preview-modal" role="dialog" aria-modal="true" aria-label="参考图片预览"><button type="button" class="uploaded-image-preview-close" aria-label="关闭预览" @click="closeUploadedImagePreview">×</button><button v-if="uploadedImages.length > 1" type="button" class="uploaded-image-preview-nav previous" aria-label="上一张" @click="showPreviousUploadedImage">‹</button><div class="uploaded-image-preview-stage"><img :src="previewImage.src" :alt="previewImage.name" /></div><button v-if="uploadedImages.length > 1" type="button" class="uploaded-image-preview-nav next" aria-label="下一张" @click="showNextUploadedImage">›</button><div class="uploaded-image-preview-footer"><span class="uploaded-image-preview-name">{{ previewImage.name }}</span><span>{{ (previewImageIndex ?? 0) + 1 }} / {{ uploadedImages.length }}</span></div><div v-if="uploadedImages.length > 1" class="uploaded-image-preview-thumbs"><button v-for="(image, index) in uploadedImages" :key="image.id" type="button" :class="{ active: previewImageIndex === index }" :aria-label="`切换到第 ${index + 1} 张图片`" @click="openUploadedImagePreview(index)"><img :src="image.src" :alt="image.name" /></button></div></article></div><div v-if="showImageSizeModal" class="image-size-modal-backdrop" @click.self="cancelImageSize"><article class="image-size-modal" role="dialog" aria-modal="true" aria-labelledby="image-size-title"><button type="button" class="image-size-close" aria-label="关闭" @click="cancelImageSize">×</button><h3 id="image-size-title">设置图像尺寸</h3><p class="image-size-current">当前：{{ imageSizeLabel }}</p><div class="image-size-tabs"><button type="button" :class="{ active: imageSizeMode === 'auto' }" @click="imageSizeMode = 'auto'">自动</button><button type="button" :class="{ active: imageSizeMode === 'ratio' }" @click="imageSizeMode = 'ratio'">按比例</button><button type="button" :class="{ active: imageSizeMode === 'custom' }" @click="imageSizeMode = 'custom'">自定义比例</button></div><template v-if="imageSizeMode === 'auto'"><div class="size-info-card"><strong>自动</strong><span>由模型自动决定输出尺寸。</span></div><div class="size-result-card"><span>将使用</span><strong>auto</strong></div></template><template v-else><div class="size-field-title">基准分辨率</div><div class="resolution-grid"><button type="button" :class="{ active: imageSizeResolution === 'standard1k' }" @click="imageSizeResolution = 'standard1k'">标准1K</button><button type="button" :class="{ active: imageSizeResolution === 'high2k' }" @click="imageSizeResolution = 'high2k'">高清2K</button><button type="button" :class="{ active: imageSizeResolution === 'ultra4k' }" @click="imageSizeResolution = 'ultra4k'">超清4K</button></div><template v-if="imageSizeMode === 'ratio'"><div class="size-field-title">图像比例</div><div class="ratio-grid"><button v-for="ratio in ['1:1','4:5','3:4','2:3','9:16','3:2','4:3','16:9','21:9','5:4','5:7','7:5','2:1','1:2','9:21']" :key="ratio" type="button" :class="{ active: imageSizeRatio === ratio }" @click="imageSizeRatio = ratio"><span class="ratio-icon" :class="`ratio-${ratio.replace(':','-')}`"></span>{{ ratio }}</button></div></template><template v-else><div class="size-field-title">输入自定义比例</div><input v-model="imageCustomRatio" class="custom-ratio-input" placeholder="16:9" /></template><div class="size-result-card"><span>将使用</span><strong>{{ imageSizeLabel }}</strong></div></template><div class="image-size-modal-actions"><button type="button" @click="cancelImageSize">取消</button><button type="button" class="confirm" @click="confirmImageSize">确认</button></div></article></div></div><div v-else class="common-tool-panel" role="tabpanel"><span class="common-tool-icon mint">◇</span><h2>去水印</h2><p>上传图片后，快速清理画面中的水印内容。</p></div></section></template><template v-else><header class="topbar"><div class="breadcrumb"><span>工作台</span><b>/</b><strong>发现</strong></div><div class="top-actions"><button type="button" aria-label="帮助" @click="notify('点击分类筛选工具，点击卡片查看详情。')">?</button><button type="button" aria-label="通知" @click="notify('目前没有新的通知')">♧</button></div></header><section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><span class="eyebrow">AI TOOL DISCOVERY</span><h1 id="hero-title">找到下一个<br><strong>改变工作方式的工具</strong></h1><p>精选优质 AI 应用，让灵感即刻落地。</p><label class="search-box"><span aria-hidden="true">⌕</span><input id="search" v-model="query" type="search" placeholder="搜索 AI 工具、功能或场景..." aria-label="搜索 AI 工具" /><kbd>⌘ K</kbd></label></div><div class="hero-orb" aria-hidden="true">✦</div></section>
      <section class="section-block" aria-labelledby="popular-title"><div class="section-heading"><div><h2 id="popular-title">热门推荐</h2><p>大家都在使用的高效工具</p></div><a href="#category-sections">查看全部 →</a></div><div class="trend-grid"><article v-for="(tool, index) in popularTools" :key="tool.name" class="trend-item" @click="selectedTool = tool"><span class="rank">0{{ index + 1 }}</span><span class="mini-icon" :class="tool.tone">{{ tool.icon }}</span><span><strong>{{ tool.name }}</strong><small>{{ tool.tagline }}</small></span><span class="arrow">↗</span></article></div></section>
      <section id="workspace-tools" class="section-block workspace-section" aria-labelledby="workspace-title"><div class="section-heading"><div><h2 id="workspace-title">常用工具</h2><p>把高频工具固定到工作台，打开即用</p></div><span class="workspace-count">{{ workspaceTools.length }}/6 已固定</span></div><div v-if="workspaceTools.length" class="workspace-grid"><article v-for="tool in workspaceTools" :key="tool.name" class="workspace-card" @click="selectedTool = tool"><div class="workspace-card-top"><span class="tool-icon" :class="tool.tone">{{ tool.icon }}</span></div><strong>{{ tool.name }}</strong><span>{{ tool.tagline }}</span><div class="workspace-open">打开工具 <b>↗</b></div></article></div><div v-else class="workspace-empty"><span class="workspace-empty-icon">⌘</span><div><strong>把常用工具放到这里</strong><p>在工具详情中点击“固定到工作台”，快速建立你的专属入口。</p></div></div></section>
      <section v-if="favoriteTools.length" class="section-block" aria-labelledby="favorites-title"><div class="section-heading"><div><h2 id="favorites-title">我的收藏</h2><p>你收藏的 AI 工具</p></div><a href="#category-sections" @click.prevent="showFavorites">查看更多 →</a></div><div class="tool-grid"><article v-for="tool in favoriteTools.slice(0, 8)" :key="tool.name" class="tool-card" @click="selectedTool = tool"><div class="card-top"><span class="tool-icon" :class="tool.tone">{{ tool.icon }}</span><div><h3>{{ tool.name }}</h3><span class="tagline">{{ tool.tagline }}</span></div></div><p>{{ tool.description }}</p><span class="category-label">{{ tool.category }}</span></article></div></section>
      <div id="category-sections"><section v-for="section in categorySections" :key="section.category" class="section-block category-section" :aria-labelledby="`category-${section.category}`"><div class="section-heading"><div><h2 :id="`category-${section.category}`">{{ section.category }}</h2><p>精选 {{ section.category }} 工具</p></div><a href="#category-sections" @click.prevent="selectCategory(section.category)">查看更多 →</a></div><div v-if="section.tools.length" class="tool-grid"><article v-for="tool in section.tools" :key="tool.name" class="tool-card" @click="selectedTool = tool"><div class="card-top"><span class="tool-icon" :class="tool.tone">{{ tool.icon }}</span><div><h3>{{ tool.name }}</h3><span class="tagline">{{ tool.tagline }}</span></div></div><p>{{ tool.description }}</p><span class="category-label">{{ tool.category }}</span></article></div><div v-else class="category-empty"><p>该分类暂时还没有工具</p><button type="button" class="submit-button" @click="notify(`已打开「${section.category}」提交入口`)" >我要提交</button></div></section></div><footer class="footer"><span>© 2026 灵感 AI 导航</span><span>发现工具，保持灵感</span></footer></template></main>
    <Transition name="fade"><div v-if="selectedImage" class="image-detail-backdrop" @click.self="selectedImage = null"><article class="image-detail-modal" role="dialog" aria-modal="true" aria-labelledby="image-detail-title"><section class="image-detail-visual"><div class="image-detail-topline"><span>{{ selectedImage.ratio }}</span><span>{{ selectedImage.size }}</span><button type="button" aria-label="下载图片" @click="notify('图片下载功能即将开放')">⇩</button></div><div class="image-detail-art" :class="`image-tone-${selectedImage.tone}`"><span>✦</span></div></section><section class="image-detail-info"><button type="button" class="image-detail-close" aria-label="关闭" @click="selectedImage = null">×</button><div class="image-detail-prompt-label">输入内容 <button type="button" aria-label="复制提示词" @click="notify('提示词已复制')">▣</button></div><p class="image-detail-prompt">{{ selectedImage.detail }}</p><div class="image-detail-divider"></div><h3 id="image-detail-title">参数配置</h3><div class="image-detail-grid"><div><span>生图模型</span><strong>gpt-image-2</strong></div><div><span>模式</span><strong>编辑</strong></div><div><span>尺寸</span><strong>{{ selectedImage.size }} <em>{{ selectedImage.size }}</em></strong></div><div><span>质量</span><strong>-</strong></div><div><span>格式</span><strong>PNG</strong></div><div><span>透明背景</span><strong>否</strong></div><div><span>数量</span><strong>1</strong></div><div><span>分辨率</span><strong>{{ selectedImage.size }}</strong></div></div><p class="image-detail-created">创建于 2026/10/02 21:38:54 · 耗时 00:41</p><div class="image-detail-actions"><button type="button" @click="notify('已复制图片配置')">↻ 复制配置</button><button type="button" @click="notify('编辑输出功能即将开放')">▣ 编辑输出</button><button type="button" class="danger" @click="notify('已移入回收站')">▣ 删除图片</button><button type="button" class="image-detail-like" aria-label="收藏图片" @click="notify('已收藏图片')">♡</button></div></section></article></div></Transition><Transition name="fade"><div v-if="showAuth" class="modal-backdrop" @click.self="closeAuth"><article class="modal auth-modal" role="dialog" aria-modal="true" aria-labelledby="auth-title"><button class="modal-close" type="button" aria-label="关闭" @click="closeAuth">×</button><span class="eyebrow">WELCOME BACK</span><h2 id="auth-title">{{ authMode === 'login' ? '登录灵感 AI 导航' : '创建你的账号' }}</h2><p class="modal-tagline">{{ authMode === 'login' ? '登录后同步收藏和个人偏好。' : '注册后即可保存你的专属工具收藏。' }}</p><form class="auth-form" @submit.prevent="submitAuth"><label v-if="authMode === 'register'">昵称<input v-model="authForm.name" type="text" placeholder="你的昵称" autocomplete="name" /></label><label>邮箱<input v-model="authForm.email" type="email" placeholder="name@example.com" autocomplete="email" /></label><label>密码<input v-model="authForm.password" type="password" placeholder="至少 6 位密码" autocomplete="current-password" /></label><label v-if="authMode === 'register'">确认密码<input v-model="authForm.confirmPassword" type="password" placeholder="再次输入密码" autocomplete="new-password" /></label><label v-if="authMode === 'login'" class="remember-row"><input v-model="authForm.remember" type="checkbox" /> 记住登录状态</label><button class="primary-button auth-submit" type="submit">{{ authMode === 'login' ? '登录' : '注册' }}</button></form><button type="button" class="auth-switch" @click="authMode = authMode === 'login' ? 'register' : 'login'">{{ authMode === 'login' ? '还没有账号？立即注册' : '已有账号？返回登录' }}</button></article></div></Transition>
    <Transition name="fade"><div v-if="selectedTool" class="modal-backdrop" @click.self="selectedTool = null"><article class="modal" role="dialog" aria-modal="true" :aria-label="selectedTool.name"><button class="modal-close" type="button" aria-label="关闭" @click="selectedTool = null">×</button><span class="tool-icon large" :class="selectedTool.tone">{{ selectedTool.icon }}</span><span class="eyebrow">{{ selectedTool.category }}</span><h2>{{ selectedTool.name }}</h2><p class="modal-tagline">{{ selectedTool.tagline }}</p><p>{{ selectedTool.description }}</p><div class="modal-actions"><button type="button" class="primary-button" @click="toggleFavorite(selectedTool)">{{ isFavorite(selectedTool) ? '★ 取消收藏' : '☆ 收藏工具' }}</button><button v-if="!workspaceToolNames.includes(selectedTool.name)" type="button" class="secondary-button" @click="addWorkspaceTool(selectedTool)">＋ 固定到工作台</button></div></article></div></Transition><Transition name="toast"><div v-if="toast" class="toast" role="status">{{ toast }}</div></Transition>
  </div>
</template>












